package com.plagnito.toulouseville;

import android.Manifest;
import android.app.*;
import android.appwidget.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.os.Build;
import android.widget.*;
import org.json.*;
import java.util.*;

final class PersonalController {
    private final MainActivity host;private final PersonalStore store;
    private JSONArray steps=new JSONArray();private JSONObject tourResult;
    PersonalController(MainActivity host){this.host=host;store=new PersonalStore(host);}
    boolean isStop(JSONObject stop){return store.contains("stops",stop.optString("id"));}
    void toggleStop(JSONObject stop){store.toggle("stops",stop,stop.optString("id"));DeparturesWidget.updateAll(host);RefreshJobs.sync(host);}
    void show(){LinearLayout box=host.column();box.addView(Art.feature(host,R.drawable.ic_devices,MainActivity.INK,host.account.connected()?"Tes trajets sont dans ton compte Atlas":"Retrouve tes trajets partout",host.account.connected()?"Ils te suivent sur le site et tes autres appareils.":"Avec un compte Atlas, ils te suivent d’un appareil à l’autre."));box.addView(Art.button(host,R.drawable.ic_account,host.account.connected()?"Ouvrir mon compte Atlas":"Se connecter avec Atlas",host.account::show));
        box.addView(Art.section(host,R.drawable.ic_stop,"Mes arrêts Tisséo"));List<JSONObject> stops=store.entries("stops");if(stops.isEmpty())box.addView(Art.empty(host,R.drawable.ill_stops,"Aucun arrêt enregistré","Ouvre la fiche d’un arrêt et enregistre-le : ses passages seront ici, et en widget sur l’écran d’accueil."));for(JSONObject stop:stops)box.addView(host.resultRow(R.drawable.ic_stop,MainActivity.ACCENT,stop.optString("name"),"Prochains passages","",()->host.stopDetail(stop)));
        box.addView(Art.section(host,R.drawable.ic_route,"Mes trajets Tisséo"));List<JSONObject> journeys=store.entries("journeys");if(journeys.isEmpty())box.addView(Art.empty(host,R.drawable.ill_empty,"Aucun trajet sur ce téléphone","Dans « Itinéraire », touche « Enregistrer » pour garder un trajet ici."));for(JSONObject journey:journeys){box.addView(host.resultRow(R.drawable.ic_route,MainActivity.INK,journey.optString("name"),"Calculer maintenant","",()->host.request("/api/journey?from="+Api.q(journey.optString("from"))+"&to="+Api.q(journey.optString("to")),host::journeyResult,e->host.toast(e.getMessage()))));box.addView(Art.button(host,R.drawable.ic_trash,"Retirer « "+journey.optString("name")+" »",()->{store.toggle("journeys",journey,journey.optString("id"));show();}));}box.addView(Art.note(host,R.drawable.ic_refresh,"Les passages et les trajets sont recalculés à chaque consultation."));host.showSheet("Mes déplacements",box);}
    void saveJourney(String from,String to){from=from.trim();to=to.trim();if(from.isEmpty()||to.isEmpty()){host.toast("Choisis le départ et l’arrivée.");return;}try{String id=from+" → "+to;JSONObject j=new JSONObject().put("id",id).put("name",id).put("from",from).put("to",to);store.toggle("journeys",j,id);host.toast(store.contains("journeys",id)?"Trajet enregistré":"Trajet retiré");}catch(Exception ignored){}}
    void lines(){LinearLayout box=host.column();box.addView(Art.feature(host,R.drawable.ic_bell,MainActivity.ACCENT,"Suis les perturbations de tes lignes","Coche tes lignes ci-dessous. Les notifications sont désactivées au départ."));CheckBox enabled=new CheckBox(host);enabled.setText("Notifications des lignes choisies");enabled.setChecked(store.alertsEnabled());box.addView(enabled);enabled.setOnCheckedChangeListener((v,on)->{if(on&&Build.VERSION.SDK_INT>=33&&host.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED){host.requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},83);return;}store.enableAlerts(on);RefreshJobs.sync(host);if(on)RefreshJobs.now(host);});
        box.addView(Art.button(host,R.drawable.ic_clock,"Horaires des notifications",()->{LinearLayout hours=host.column();Spinner start=hour(hours,store.prefs.getInt("alert_from",8)),end=hour(hours,store.prefs.getInt("alert_to",22));hours.addView(host.text("Début, puis fin. Même heure : toute la journée.",12,MainActivity.MUTED,false));new AlertDialog.Builder(host).setTitle("Plage horaire").setView(hours).setPositiveButton("Enregistrer",(d,w)->store.prefs.edit().putInt("alert_from",start.getSelectedItemPosition()).putInt("alert_to",end.getSelectedItemPosition()).apply()).setNegativeButton("Annuler",null).show();}));
        box.addView(Art.note(host,R.drawable.ic_clock,"Android vérifie environ toutes les 15 minutes, parfois plus tard selon la batterie."));box.addView(Art.note(host,R.drawable.ic_info,"Le premier relevé sert de référence : seules les alertes nouvelles ou modifiées notifient ensuite."));box.addView(Art.section(host,R.drawable.ic_bus,"Mes lignes"));LinearLayout list=host.column();box.addView(list);host.request("/api/routes",j->{JSONArray routes=j.optJSONArray("routes");if(routes==null){list.addView(host.text("Lignes indisponibles",13,MainActivity.MUTED,false));return;}List<JSONObject> sorted=new ArrayList<>();for(int i=0;i<routes.length();i++)if(routes.optJSONObject(i)!=null)sorted.add(routes.optJSONObject(i));sorted.sort(Comparator.comparing(r->r.optString("name",r.optString("short"))));for(JSONObject route:sorted){String id=route.optString("id",route.optString("route_id"));String name=route.optString("route_short_name",route.optString("short",route.optString("name",id)));CheckBox check=new CheckBox(host);check.setText(name+" · "+route.optString("route_long_name",route.optString("long")));check.setChecked(store.contains("lines",id));list.addView(check);check.setOnCheckedChangeListener((v,on)->{try{JSONObject item=new JSONObject().put("id",id).put("name",name);if(on!=store.contains("lines",id))store.toggle("lines",item,id);if(on&&!store.contains("lines",id)){check.setChecked(false);host.toast("30 lignes maximum.");}RefreshJobs.sync(host);if(store.alertsEnabled())RefreshJobs.now(host);}catch(Exception ignored){}});}},e->list.addView(host.text(e.getMessage(),13,MainActivity.MUTED,false)));host.showSheet("Lignes & alertes Tisséo",box);}
    private Spinner hour(LinearLayout box,int chosen){Spinner spinner=new Spinner(host);String[] hours=new String[24];for(int i=0;i<24;i++)hours[i]=String.format(Locale.FRENCH,"%02d h",i);spinner.setAdapter(new ArrayAdapter<>(host,android.R.layout.simple_spinner_dropdown_item,hours));spinner.setSelection(chosen);box.addView(spinner);return spinner;}
    void permissionResult(){boolean allowed=RefreshJobs.notificationAllowed(host);store.enableAlerts(allowed);RefreshJobs.sync(host);if(allowed)RefreshJobs.now(host);else host.toast("Notifications non autorisées. Les alertes restent consultables dans l’app.");lines();}
    void widget(JSONObject stop){if(!isStop(stop)){store.toggle("stops",stop,stop.optString("id"));}AppWidgetManager manager=AppWidgetManager.getInstance(host);LinearLayout box=host.column();box.addView(Art.hero(host,R.drawable.ill_stops));box.addView(host.text("Widget Tisséo · "+stop.optString("name"),17,MainActivity.INK,true));box.addView(Art.note(host,R.drawable.ic_clock,"Les heures affichées sont celles du dernier relevé, avec sa date."));box.addView(Art.note(host,R.drawable.ic_refresh,"Actualise avant de partir : Android peut différer les mises à jour."));if(manager.isRequestPinAppWidgetSupported())box.addView(Art.primary(host,R.drawable.ic_widget,"Ajouter à l’écran d’accueil",()->{Intent callback=new Intent(host,WidgetPinnedReceiver.class).putExtra("stop_id",stop.optString("id"));PendingIntent done=PendingIntent.getBroadcast(host,stop.optString("id").hashCode(),callback,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_MUTABLE);boolean accepted=manager.requestPinAppWidget(new ComponentName(host,DeparturesWidget.class),null,done);if(!accepted)host.toast("Ajoute le widget depuis le menu Widgets du téléphone.");}));else box.addView(Art.note(host,R.drawable.ic_widget,"Ajoute le widget depuis le menu Widgets de l’écran d’accueil."));host.showSheet("Prochains passages",box);}
    void clearTour(){steps=new JSONArray();tourResult=null;}
    void addStep(JSONObject p){if(steps.length()>=6){host.toast("Six étapes maximum.");return;}if(steps.length()>0&&steps.optJSONObject(steps.length()-1).optString("id").equals(p.optString("id"))){host.toast("Ce lieu est déjà la dernière étape.");return;}steps.put(p);tourResult=null;host.setGeo("walking",host.emptyCollection());host.setGeo("tour-points",host.emptyCollection());tour();}
    void tour(){LinearLayout box=host.column();if(steps.length()==0)box.addView(Art.empty(host,R.drawable.ill_walk,"Compose ta balade","Ouvre la fiche d’un lieu et touche « Ajouter à ma balade ». Il en faut 2 à 6."));else box.addView(Art.note(host,R.drawable.ic_info,"De 2 à 6 lieux, dans l’ordre de visite. La durée est celle de la marche, hors visites et pauses."));for(int i=0;i<steps.length();i++){int index=i;JSONObject p=steps.optJSONObject(i);box.addView(Art.numbered(host,i+1,p.optString("name"),true));LinearLayout row=host.row();row.setPadding(host.dp(34),0,0,host.dp(6));if(i>0)row.addView(host.button("Monter",()->{swap(index,index-1);tour();}));if(i<steps.length()-1)row.addView(host.button("Descendre",()->{swap(index,index+1);tour();}));row.addView(Art.button(host,R.drawable.ic_trash,"Retirer",()->{steps.remove(index);changed();tour();}));box.addView(row);}if(steps.length()>=2)box.addView(Art.primary(host,R.drawable.ic_route,"Calculer ma balade",()->{StringJoiner points=new StringJoiner(";");for(int i=0;i<steps.length();i++){JSONObject p=steps.optJSONObject(i);points.add(p.optDouble("lat")+","+p.optDouble("lon"));}host.toast("Calcul des chemins piétons…");String requested=steps.toString();host.request("/api/city/tour?points="+Api.q(points.toString()),j->{if(!requested.equals(steps.toString()))return;tourResult=j;host.drawTour(j,steps);tour();},e->host.toast(e.getMessage()));}));if(tourResult!=null){box.addView(Art.grid(host,Art.stat(host,R.drawable.ic_clock,MainActivity.ACCENT,(int)Math.ceil(tourResult.optDouble("duration_s")/60)+" min","de marche"),Art.stat(host,R.drawable.ic_route,Art.OK,String.format(Locale.FRENCH,"%.1f km",tourResult.optDouble("distance_m")/1000),"à parcourir")));JSONArray legs=tourResult.optJSONArray("legs");for(int i=0;legs!=null&&i<legs.length();i++){JSONObject leg=legs.optJSONObject(i);box.addView(host.text((i+1)+" → "+(i+2)+" : "+(int)Math.ceil(leg.optDouble("duration_s")/60)+" min",14,MainActivity.ACCENT,true));JSONArray instructions=leg.optJSONArray("instructions");for(int k=0;instructions!=null&&k<instructions.length();k++)box.addView(host.text(instructions.optJSONObject(k).optString("text"),13,MainActivity.MUTED,false));}if(!tourResult.optString("notice").isEmpty())box.addView(Art.note(host,R.drawable.ic_info,tourResult.optString("notice")));box.addView(Art.button(host,R.drawable.ic_share,"Partager ma balade",()->{StringBuilder text=new StringBuilder("Balade à "+host.city.name()+"\n");for(int i=0;i<steps.length();i++)text.append(i+1).append(". ").append(steps.optJSONObject(i).optString("name")).append("\n");text.append((int)Math.ceil(tourResult.optDouble("duration_s")/60)).append(" min de marche estimées, hors visites.\nhttps://tisseo.plagnito.com/?vue=ville&city=").append(Api.q(host.city.id()));try{host.startActivity(Intent.createChooser(new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,text.toString()),"Partager ma balade"));}catch(ActivityNotFoundException e){host.toast("Partage indisponible.");}}));}if(steps.length()>0)box.addView(Art.button(host,R.drawable.ic_trash,"Vider les étapes",()->{clearTour();changed();tour();}));host.showSheet("Ma balade à étapes",box);}
    private void changed(){tourResult=null;host.setGeo("walking",host.emptyCollection());host.setGeo("tour-points",host.emptyCollection());}
    private void swap(int a,int b){try{JSONObject first=steps.getJSONObject(a);steps.put(a,steps.getJSONObject(b));steps.put(b,first);changed();}catch(Exception ignored){}}
}
